// Recorded agent runs, replayed when LLM="scripted". The files in __scripts__/ are generated by
// `npm run agent:scripts` from the demo repo's reference solutions.
import type { Intent } from "../../shared/types";
import type { LlmTurn, ScriptedTurns } from "../ports/llm";

const PREFIX = "./__scripts__/";
const files = import.meta.glob<LlmTurn[]>("./__scripts__/*.json", { import: "default", eager: true });

/** Script key (file name without .json) -> turns. */
export const AGENT_SCRIPTS: ScriptedTurns = Object.fromEntries(Object.entries(files).map(([path, turns]) => [path.slice(PREFIX.length).replace(/\.json$/, ""), turns]));

/** The script for a task: "<taskId>" for a fresh run, "<taskId>.rederive" for a re-derive. */
export function scriptKey(intent: Pick<Intent, "taskId">, mode: "fresh" | "rederive", override?: string): string {
	return override ?? (mode === "rederive" ? `${intent.taskId}.rederive` : intent.taskId);
}
